#!/usr/bin/env python3
import json,statistics as s,collections
from pathlib import Path
D=Path(__file__).resolve().parent
def read(n):return [json.loads(x) for x in (D/n).read_text().splitlines() if x]
def strata(y):
 try:y=int(y)
 except (TypeError,ValueError):return 'unknown'
 return 'pre-2015' if y<2015 else '2015–19' if y<2020 else '2020 onward'
def dist(a,key):
 v=[x[key] for x in a if x.get(key) is not None]
 return (min(v),s.median(v),max(v)) if v else (None,None,None)
archive=read('public_archive_measurements.jsonl');a=[x for x in archive if x['extraction_status']=='measured'];lf=read('longform_dated_candidates.jsonl');probe=read('longform_public_probes.jsonl');bio=read('measurements.jsonl');discover=json.loads((D/'discovery.json').read_text());manual=read('manual-screen.jsonl')
lines=['# Essay corpus: discovery and first measurements','', '16 November 2026. This is an exploratory acquisition and extraction run, not an accepted form profile. The two provisional forms can overlap. None of the numeric observations is a writing target or a limit. The 200-per-form goal is **not met**: four individual texts were screened by one reviewer, two per form.','', '| Collection | Discovery / selected | Acquired and mechanically extracted | Form eligibility |', '| --- | --- | --- | --- |',f'| Longform essay-tag archive | {len(lf)} distinct target URLs, editorially selected; full tag through page 19 | 25 publisher-domain probes; {sum(x["status"]=="extracted_unvalidated" for x in probe)} returned at least 100 extracted article words, body completeness unverified | No full-text eligibility decisions |',f'| Paul Graham original essay archive | {len(read("public_archive_candidates.jsonl"))} distinct index links; first 225 selected in index order | {len(a)} with at least 100 extracted words; {len(archive)-len(a)} yielded too little | Four one-reviewer provisional inclusions; multiple forms possible |',f'| Europe PMC personal narrative indexing | {discover["personal_reflective"]["total_query_hits"]} search hits; 300 selected | {sum(x["form_candidate"]=="personal_reflective" and x["extraction_status"]=="measured" for x in bio)} bodies extracted | Not manually screened; publication-type labels contain clear mismatches |',f'| Europe PMC editorial indexing | {discover["argument_perspective"]["total_query_hits"]:,} search hits; 300 selected | {sum(x["form_candidate"]=="argument_perspective" and x["extraction_status"]=="measured" for x in bio)} bodies extracted | Not manually screened; publication-type labels contain clear mismatches |','', 'The selected collections overlap in possible form and may overlap in work identity; do not add their counts to claim a deduplicated form corpus. The archive is one author and cannot estimate a general personal-essay or argument distribution. The biomedical sample is a separate disciplinary cohort. Its citation sort is a retrieval-specific metric, not literary importance or readership.','', '## Historical strata','', 'Year for the author archive is the first year in its original date label; labels sometimes include revisions. Longform dates are displayed index metadata and should be checked against original publication. Europe PMC uses its indexed `pubYear`. Unknown stays separate.','', '| Collection | Pre-2015 | 2015–19 | 2020 onward | Unknown |','| --- | ---: | ---: | ---: | ---: |']
for label,rows,key in [('Longform candidates',lf,'year_display'),('Paul Graham extracted',a,'publication_year'),('Europe PMC extracted', [x for x in bio if x['extraction_status']=='measured'],'pubYear')]:
 c=collections.Counter(strata(x.get(key)) for x in rows);lines.append(f'| {label} | {c["pre-2015"]} | {c["2015–19"]} | {c["2020 onward"]} | {c["unknown"]} |')
lines+=['','The [historical discovery note](historical-discovery.md) links an independent editorial list, a publisher award/finalist register and specific library leads. Accolades and editorial inclusion are recorded distinctly; neither is a readership ranking.','','## Observations within the single-author archive','','The table describes only extracted pages from this author’s index, with no classification by form. The word unit and extraction rules below matter when comparing strata. Each paragraph figure is the median of the individual documents’ median paragraph lengths, avoiding simple weighting toward long documents.','', '| Date stratum | Documents | Body words: min / median / max | Median of document paragraph medians |','| --- | ---: | ---: | ---: |']
for z in ('pre-2015','2015–19','2020 onward','unknown'):
 b=[x for x in a if strata(x.get('publication_year'))==z];lo,mid,hi=dist(b,'body_prose_words');para=s.median([s.median(x['paragraph_words']) for x in b]) if b else '—';lines.append(f'| {z} | {len(b)} | {lo} / {mid} / {hi} | {para} |')
lines+=['','These differences are descriptive only. Index-order selection, changes in topic and genre, parser errors, and this single author all confound temporal comparisons. Four checked examples are below; one-reviewer form judgment is provisional, and no claim facts were verified.','','| Example | Year | Provisional form | Extracted body words | Paragraphs |','| --- | ---: | --- | ---: | ---: |']
for m in manual:
 x=next((x for x in a if x['source_url']==m['url']),None)
 if x:lines.append(f'| [{x["title"]}]({m["url"]}) | {x.get("publication_year")} | {m["form"].replace("_"," / ")} | {x["body_prose_words"]} | {x["paragraph_count"]} |')
lines+=['','## Method, provenance, limits','','- `longform_dated_candidates.jsonl` and `longform_dated_pages.jsonl` retain displayed metadata, links, search pages, hashes and retrieval times. `longform_public_probes.jsonl` records retrieval refusals, redirects, paywall declarations and provisional extraction outcomes. No paywall was bypassed; a returned article body has not been checked for completeness.','- One page per publisher domain was probed after checking robots; non-200 robots and non-200 article responses were skipped. A manual preliminary Guernica page request and the subsequent automated probe occurred within Guernica’s 600-second crawl delay. That was an access-rate error; no further Guernica requests were made.','- `public_archive_candidates.jsonl` and `public_archive_measurements.jsonl` record author-index links and page hashes. Body paragraphs are estimated from the longest Verdana block and double line breaks; leading promotions/date and notes are excluded when identified. The 100-word cutoff is an extraction triage rule, not an eligibility or quality rule. Four pages did not yield sufficient text under this parser. Body completeness, headings, citation function, and footnote boundaries need review.','- `candidates.jsonl`, `discovery.json`, and `measurements.jsonl` preserve the Europe PMC queries, citation order, source identifiers, year, article types, XML hashes, retrieved times, extraction states and mechanical counts. The extracted JATS body excludes lists, figures, tables, formulas, boxes, captions, acknowledgments and references. Citation or quote counts do not establish supporting function. Sections without headings and repeated headings are not resolved reliably.','- The character/word and sentence/paragraph distributions are mechanical approximations; word tokenization and punctuation-based sentence splitting are defined in `acquire_measure.py`. HTML and JATS parser failures, figures, headings, notes and embedded content can distort results. No rhetorical functions were assigned by code; the [four human screening notes](manual-screen.jsonl) are not independent agreement.','- Source HTML/XML is retained only in the local `/workspace/repos/builderbob/.essay-corpus-cache/2026-11-16/` cache; these repository files contain metadata and derived statistics, not article prose. No publication, deployment, or source-content redistribution is implied.','',f'Longform probe outcomes: `{dict(collections.Counter(x["status"] for x in probe))}`. Europe PMC outcomes: `{dict(collections.Counter((x["form_candidate"],x["extraction_status"]) for x in bio))}`.','', 'To reproduce the analysis, use the three acquisition scripts only when access terms and crawl delays permit; then run `python3 experiments/form-corpus-2026-11-16/essays/summarize.py`. Acquisition can change as pages, access and rankings change. For a stronger form study, screen individual texts and source editions, broaden authors/outlets and historic works, compare independent reviewers, and extract accessible library texts without bypassing access controls.','']
(D/'summary.md').write_text('\n'.join(lines))
